environment = os.environ.copy()
build_root = Path(tempfile.mkdtemp(prefix='g-switcher-word-build-', dir=os.environ.get('RUNNER_TEMP')))
environment['CARGO_TARGET_DIR'] = str(build_root / 'cargo-target')

